{"function": "() => {
    // Try to find transcript container by searching for text "Transcript"
    const container = document.querySelector('ytd-transcript-renderer');
    if (!container) {
        // Maybe inside a dialog
        const dialog = document.querySelector('ytd-transcript-search-panel-renderer');
        if (dialog) {
            container = dialog.querySelector('ytd-transcript-renderer');
        }
    }
    if (container) {
        const segments = container.querySelectorAll('ytd-transcript-segment-renderer');
        if (segments.length) {
            return Array.from(segments).map(s => s.innerText);
        }
    }
    // Alternative: find all elements with role="listitem" inside transcript
    const listItems = document.querySelectorAll('[role="listitem"]');
    const transcriptItems = Array.from(listItems).filter(li => li.closest('ytd-transcript-renderer'));
    if (transcriptItems.length) {
        return transcriptItems.map(li => li.innerText);
    }
    // Fallback: get all text in the transcript panel
    const panel = document.querySelector('ytd-transcript-search-panel-renderer');
    if (panel) {
        return panel.innerText;
    }
    return 'No transcript found';
}"}

