    return {
        title,
        channelName,
        subscriberCount,
        viewCount,
        uploadDate,
        description,
        commentsCount: commentElements.length,
        comments,
        transcriptLinesCount: transcriptLines.length,
        transcriptLines,
        url: window.location.href
    };
}"}

